fn sum_owned(v: Vec[Int]) -> Int {
  var total = 0;
  var i = 0;
  while i < v.len() {
    total = total + v[i];
    i = i + 1;
  }
  return total;
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(1);
  v.push(2);
  v.push(3);
  return sum_owned(v);
}
